const crypto = require("crypto");

var storage;
var sessionExpiryTime;

const buildTokenKey = (token) => {
    return `session-tokens:${token}`;
}

module.exports = {
    init: function(adminAuthSettings, _storage) {
        storage = _storage;
        sessionExpiryTime = adminAuthSettings.sessionExpiryTime || 604800; // 1 week in seconds
        if ( Array.isArray(adminAuthSettings.tokens) ) {
            for (const token of adminAuthSettings.tokens) {
                storage.TokenSession().set(buildTokenKey(token.token), JSON.stringify({
                    user: token.user,
                    scope: token.scope
                }), 0).catch(function(error) {
                    console.error("Error setting token:", error);
                });
            }
        }
    },
    get: function(token) {
        return storage.TokenSession().get(buildTokenKey(token)).then(function(session) {
            if(!session) {
                return Promise.resolve(null);
            }
            return Promise.resolve(JSON.parse(session));
        });
    },
    create: async function(user,client,scope) {
        const token = crypto.randomBytes(128).toString('base64');
        const session = {
            user: user,
            client: client,
            scope: scope,
            accessToken: token,
            expires: Date.now() + (sessionExpiryTime * 1000)
        }
        return storage.TokenSession().set(buildTokenKey(token), JSON.stringify(session), sessionExpiryTime).then(function() {
            return {
                accessToken: token,
                expires_in: sessionExpiryTime
            }
        });
    },
    revoke: async function(token) {
        try {
            const key = buildTokenKey(token);
            const sessionData = await storage.TokenSession().get(key);
            const session = JSON.parse(sessionData);
            await Promise.all([
                storage.TokenSession().delete(`sessions:${session.user}`),
                storage.TokenSession().delete(key)
            ]);
        } catch (error) {
            console.error("Error revoking token:", error);
        }
    },
    onSessionExpiry: function(callback) {
    }
}
